package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden holds the plants assigned to each child in a kindergarten garden.
type Garden struct {
	plants map[string][]string
}

var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// NewGarden parses a diagram and assigns cups to children alphabetically.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// The diagram must consist of exactly two rows of equal, even length
// containing only the plant codes G, C, R, and V, with two cups for
// each child.  The children argument is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(diagram[1:], "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must contain exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram must contain an even number of cups")
	}
	if len(rows[0])/2 != len(children) {
		return nil, errors.New("diagram must contain two cups for each child")
	}

	for _, row := range rows {
		for _, code := range row {
			if _, ok := plantNames[code]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", code)
			}
		}
	}

	seen := make(map[string]bool, len(children))
	for _, child := range children {
		if seen[child] {
			return nil, fmt.Errorf("duplicate child name %q", child)
		}
		seen[child] = true
	}

	// Sort a copy so the caller's slice is not modified.
	names := make([]string, len(children))
	copy(names, children)
	sort.Strings(names)

	g := &Garden{plants: make(map[string][]string, len(names))}
	for i, child := range names {
		cup := 2 * i
		g.plants[child] = []string{
			plantNames[rune(rows[0][cup])],
			plantNames[rune(rows[0][cup+1])],
			plantNames[rune(rows[1][cup])],
			plantNames[rune(rows[1][cup+1])],
		}
	}
	return g, nil
}

// Plants returns the four plants belonging to the named child, in the
// order: first row left cup, first row right cup, second row left cup,
// second row right cup.  The ok result is false if the child is not
// in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}
